    Bug 1923984 - Avoid some unnecessary copies in ExchangeMessageCreate. r=mkmelin


    Coverity spotted a couple of places where a var could be moved instead of copied.

    CID: 1690681
    CID: 1690682

    Differential Revision: https://phabricator.services.mozilla.com/D290567

diff --git a/mailnews/protocols/exchange/src/ExchangeMessageCreate.cpp b/mailnews/protocols/exchange/src/ExchangeMessageCreate.cpp
index 7bfce43b450..de2877c7557 100644
--- a/mailnews/protocols/exchange/src/ExchangeMessageCreate.cpp
+++ b/mailnews/protocols/exchange/src/ExchangeMessageCreate.cpp
@@ -199,7 +199,7 @@ nsresult ExchangePerformMessageCreate(

   // Creation without copying an existing nsIMsgDBHdr.
   RefPtr<MessageCreateHandler> handler = new MessageCreateHandler(
-      destFolder, srcRaw, nullptr, {}, isRead, isDraft, onComplete);
+      destFolder, srcRaw, nullptr, {}, isRead, isDraft, std::move(onComplete));
   return handler->Go();
 }

@@ -216,6 +216,6 @@ nsresult ExchangePerformMessageCreateFromCopy(

   RefPtr<MessageCreateHandler> handler =
       new MessageCreateHandler(destFolder, srcRaw, srcHdr, srcExcludeProperties,
-                               isRead, isDraft, onComplete);
+                               isRead, isDraft, std::move(onComplete));
   return handler->Go();
 }
